    "spill": "Spill changes from the topmost patch",
    "squash": "Squash two or more patches into one",
    "sync": "Synchronize patches with a branch or a series",
    "top": "Print the name of the top patch",
    "uncommit": "Convert regular Git commits into StGit patches",
    "undo": "Undo the last command",
    "unhide": "Unhide hidden patches",
    "version": "Print version information and exit",
    "help": "Print this message or the help of the given subcommand(s)",
}
PATCH_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")


def repo_root_from_script() -> Path:
    here = Path(__file__).resolve()
    for candidate in (here.parent, here.parent.parent):
        if (candidate / "captured" / "help_texts.json").exists():
            return candidate
    return here.parent


ROOT = repo_root_from_script()
HELP_PATH = ROOT / "captured" / "help_texts.json"
with HELP_PATH.open("r", encoding="ascii") as handle:
    HELP_TEXTS = json.load(handle)


@dataclass
class StackState:
    branch: str
    initialized: bool
    head: str
    prev: Optional[str]
    applied: list[str]
    unapplied: list[str]
    hidden: list[str]
    patches: dict[str, str]
    stack_oid: Optional[str]
    meta_oid: Optional[str]


class ParseError(Exception):
    def __init__(self, message: str, usage_key: str, extra: Optional[str] = None):
        super().__init__(message)
        self.message = message
        self.usage_key = usage_key
        self.extra = extra


class UserError(Exception):
    def __init__(self, message: str, code: int = 2):
        super().__init__(message)
        self.message = message
        self.code = code


def git(args: list[str], cwd: str, env: Optional[dict[str, str]] = None, input_text: Optional[str] = None) -> subprocess.CompletedProcess[str]:
    merged_env = os.environ.copy()
    if env:
        merged_env.update(env)
    return subprocess.run(
        ["git", *args],
        cwd=cwd,
        env=merged_env,
        input=input_text,
        text=True,
        capture_output=True,
    )


def git_ok(args: list[str], cwd: str, env: Optional[dict[str, str]] = None, input_text: Optional[str] = None) -> str:
    result = git(args, cwd, env=env, input_text=input_text)
    if result.returncode != 0:
        stderr = result.stderr.strip()
        raise UserError(stderr or "git command failed")
    return result.stdout


def passthrough(cmd: list[str], cwd: str) -> int:
    return subprocess.run(cmd, cwd=cwd).returncode


def print_text(text: str, stream: str = "stdout") -> None:
    if stream == "stdout":
        sys.stdout.write(text)
    else:
        sys.stderr.write(text)


def usage_block(help_key: str) -> str:
    text = HELP_TEXTS[help_key]["stdout"]
    lines = text.splitlines()
    block: list[str] = []
    collecting = False
    for line in lines:
        if line.startswith("Usage:"):
            collecting = True
        if collecting:
            if block and line == "":
                break
            block.append(line)
    return "\n".join(block)


def long_help_for(path: list[str]) -> str:
    if not path:
        return HELP_TEXTS["top_long"]["stdout"]
    if path == ["help"]:
        return HELP_TEXTS["help_help"]["stdout"]
    if path[0] == "completion":
        if len(path) == 1:
            return HELP_TEXTS["completion:long"]["stdout"]
        if path[1] == "list":
            if len(path) == 2:
                return HELP_TEXTS["completion_list:long"]["stdout"]
            key = "_".join(["completion", "list", path[2].replace("-", "_")])
            help_key = f"{key}:long"
            if help_key in HELP_TEXTS:
                return HELP_TEXTS[help_key]["stdout"]
        else:
            key = "_".join(["completion", path[1].replace("-", "_")])
            help_key = f"{key}:long"
            if help_key in HELP_TEXTS:
                return HELP_TEXTS[help_key]["stdout"]
    help_key = f"{path[0]}:long"
    if help_key in HELP_TEXTS:
        return HELP_TEXTS[help_key]["stdout"]
    raise ParseError(f"unrecognized subcommand '{path[0]}'", "top_short")


def short_help_for(command: str) -> str:
    return HELP_TEXTS[f"{command}:short"]["stdout"]


def parse_error(message: str, usage_key: str, extra: Optional[str] = None) -> None:
    raise ParseError(message, usage_key, extra=extra)


def user_error(message: str, code: int = 2) -> None:
    raise UserError(message, code=code)


def validate_color(value: str, usage_key: str) -> None:
    if value not in COLOR_VALUES:
        parse_error(
            f"invalid value '{value}' for '--color <when>'",
            usage_key,
            extra="  [possible values: auto, always, ansi, never]",
        )


def current_time_text() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S %z")


def author_identity(cwd: str) -> tuple[str, str]:
    name = git_ok(["config", "--get", "user.name"], cwd).strip() or "StGit User"
    email = git_ok(["config", "--get", "user.email"], cwd).strip() or "stgit@example.com"
    return name, email


def repo_root(cwd: str) -> str:
    result = git(["rev-parse", "--show-toplevel"], cwd)
    if result.returncode != 0:
        user_error("Could not find a git repository in '.' or in any of its parents")
    return result.stdout.strip()


def ensure_repo(cwd: str) -> None:
    repo_root(cwd)


def current_branch(cwd: str) -> str:
    result = git(["symbolic-ref", "--quiet", "--short", "HEAD"], cwd)
    if result.returncode != 0:
        user_error("HEAD is detached")
    return result.stdout.strip()


def branch_ref(branch: str) -> str:
    return f"refs/heads/{branch}"


def patch_ref(branch: str, patch_name: str) -> str:
    return f"refs/patches/{branch}/{patch_name}"


def stack_ref(branch: str) -> str:
    return f"refs/stacks/{branch}"


def ref_exists(cwd: str, ref: str) -> bool:
    return git(["show-ref", "--verify", "--quiet", ref], cwd).returncode == 0


def branch_head(cwd: str, branch: str) -> str:
    if current_branch(cwd) == branch:
        result = git(["rev-parse", "--verify", "HEAD"], cwd)
    else:
        result = git(["rev-parse", "--verify", branch_ref(branch)], cwd)
    if result.returncode != 0:
        user_error(f"branch `{branch_ref(branch)}` is unborn")
    return result.stdout.strip()


def load_stack(cwd: str, branch: str) -> StackState:
    head = branch_head(cwd, branch)
    ref = stack_ref(branch)
    if not ref_exists(cwd, ref):
        return StackState(
            branch=branch,
            initialized=False,
            head=head,
            prev=None,
            applied=[],
            unapplied=[],
            hidden=[],
            patches={},
            stack_oid=None,
            meta_oid=None,
        )
    stack_oid = git_ok(["rev-parse", ref], cwd).strip()
    meta_result = git(["rev-parse", f"{ref}^1"], cwd)
    meta_oid = meta_result.stdout.strip() if meta_result.returncode == 0 else None
    data = json.loads(git_ok(["show", f"{ref}:stack.json"], cwd))
    patches = {name: info["oid"] for name, info in data.get("patches", {}).items()}
    return StackState(
        branch=branch,
        initialized=True,
        head=head,
        prev=data.get("prev"),
        applied=list(data.get("applied", [])),
        unapplied=list(data.get("unapplied", [])),
        hidden=list(data.get("hidden", [])),
        patches=patches,
        stack_oid=stack_oid,
        meta_oid=meta_oid,
    )


def stack_series(state: StackState) -> list[str]:
    return [*state.applied, *state.unapplied, *state.hidden]


def patch_exists(state: StackState, patch_name: str) -> bool:
    return patch_name in state.patches


def patch_oid(state: StackState, patch_name: str) -> str:
    if patch_name not in state.patches:
        similar = difflib.get_close_matches(patch_name, sorted(state.patches), n=1)
        if similar:
            user_error(f"patch `{patch_name}` does not exist, but is similar to `{similar[0]}`")
        user_error(f"patch `{patch_name}` does not exist")
    return state.patches[patch_name]


def commit_parent(cwd: str, oid: str) -> str:
    result = git(["rev-parse", f"{oid}^"], cwd)
    if result.returncode != 0:
        user_error(f"commit `{oid}` does not have a parent")
    return result.stdout.strip()


def commit_tree(cwd: str, oid: str) -> str:
    return git_ok(["show", "-s", "--format=%T", oid], cwd).strip()


def commit_subject(cwd: str, oid: str) -> str:
    return git_ok(["show", "-s", "--format=%s", oid], cwd).strip()


def commit_message(cwd: str, oid: str) -> str:
    text = git_ok(["show", "-s", "--format=%B", oid], cwd)
    return text.rstrip("\n")


def commit_author_info(cwd: str, oid: str) -> tuple[str, str, str]:
    output = git_ok(["show", "-s", "--format=%an%n%ae%n%ai", oid], cwd).splitlines()
    return output[0], output[1], output[2]


def stack_base_oid(cwd: str, state: StackState) -> str:
    series = stack_series(state)
    if not series:
        return state.head
    return commit_parent(cwd, state.patches[series[0]])


def normalize_paths(cwd: str, paths: list[str]) -> list[str]:
    if not paths:
        return []
    root = repo_root(cwd)
    prefix = git_ok(["rev-parse", "--show-prefix"], cwd).strip()
    normalized: list[str] = []
    for path in paths:
        if os.path.isabs(path):
            normalized.append(os.path.relpath(path, root))
        elif prefix:
            normalized.append(os.path.normpath(os.path.join(prefix, path)))
        else:
            normalized.append(path)
    return normalized


def write_ref(cwd: str, ref: str, oid: str) -> None:
    git_ok(["update-ref", ref, oid], cwd)


def delete_ref(cwd: str, ref: str) -> None:
    if ref_exists(cwd, ref):
        git_ok(["update-ref", "-d", ref], cwd)


def hard_reset(cwd: str, oid: str) -> None:
    result = git(["reset", "--hard", oid], cwd)
    if result.returncode != 0:
        raise UserError(result.stderr.strip() or "could not update worktree")


def update_branch_head(cwd: str, branch: str, oid: str, update_worktree: bool) -> None:
    write_ref(cwd, branch_ref(branch), oid)
    if current_branch(cwd) == branch and update_worktree:
        hard_reset(cwd, oid)


def hash_blob(cwd: str, text: str) -> str:
    return git_ok(["hash-object", "-w", "--stdin"], cwd, input_text=text).strip()


def patch_blob_text(cwd: str, oid: str) -> str:
    author_name, author_email, author_date = commit_author_info(cwd, oid)
    bottom = commit_tree(cwd, commit_parent(cwd, oid))
    top = commit_tree(cwd, oid)
    message = commit_message(cwd, oid)
    return (
        f"Bottom: {bottom}\n"
        f"Top:    {top}\n"
        f"Author: {author_name} <{author_email}>\n"
        f"Date:   {author_date}\n\n"
        f"{message}\n"
    )


def build_stack_tree(cwd: str, state: StackState) -> str:
    with tempfile.NamedTemporaryFile() as index_file:
        env = {"GIT_INDEX_FILE": index_file.name}
        git_ok(["read-tree", "--empty"], cwd, env=env)
        stack_json = json.dumps(
            {
                "version": 5,
                "prev": state.prev,
                "head": state.head,
                "applied": state.applied,
                "unapplied": state.unapplied,
                "hidden": state.hidden,
                "patches": {name: {"oid": oid} for name, oid in sorted(state.patches.items())},
            },
            indent=2,
        ) + "\n"
        stack_blob = hash_blob(cwd, stack_json)
        git_ok(["update-index", "--add", "--cacheinfo", "100644", stack_blob, "stack.json"], cwd, env=env)
        for name in sorted(state.patches):
            blob = hash_blob(cwd, patch_blob_text(cwd, state.patches[name]))
            git_ok(["update-index", "--add", "--cacheinfo", "100644", blob, f"patches/{name}"], cwd, env=env)
        return git_ok(["write-tree"], cwd, env=env).strip()


def commit_tree_object(
    cwd: str,
    tree: str,
    message: str,
    parents: list[str],
    author: Optional[tuple[str, str, str]] = None,
    committer: Optional[tuple[str, str, str]] = None,
) -> str:
    if author is None:
        author = (*author_identity(cwd), current_time_text())
    if committer is None:
        committer = (*author_identity(cwd), current_time_text())
    env = {
        "GIT_AUTHOR_NAME": author[0],
        "GIT_AUTHOR_EMAIL": author[1],
        "GIT_AUTHOR_DATE": author[2],
        "GIT_COMMITTER_NAME": committer[0],
        "GIT_COMMITTER_EMAIL": committer[1],
        "GIT_COMMITTER_DATE": committer[2],
    }
    args = ["commit-tree", tree]
    for parent in parents:
        args.extend(["-p", parent])
    args.extend(["-m", message])
    return git_ok(args, cwd, env=env).strip()


def sync_patch_refs(cwd: str, branch: str, before: dict[str, str], after: dict[str, str]) -> None:
    for name, oid in after.items():
        if before.get(name) != oid:
            write_ref(cwd, patch_ref(branch, name), oid)
    for name in before:
        if name not in after:
            delete_ref(cwd, patch_ref(branch, name))


def write_stack_state(
    cwd: str,
    before: StackState,
    after: StackState,
    message: str,
    head_changed: bool,
    extra_meta_messages: Optional[list[str]] = None,
) -> StackState:
    tree = build_stack_tree(cwd, after)
    meta_parent = before.meta_oid
    if extra_meta_messages:
        for meta_message in extra_meta_messages:
            meta_parent = commit_tree_object(cwd, tree, meta_message, [meta_parent] if meta_parent else [])
    meta_oid = commit_tree_object(cwd, tree, message, [meta_parent] if meta_parent else [])
    parents = [meta_oid]
    if head_changed or before.stack_oid is None:
        parents.append(after.head)
    if before.stack_oid is not None:
        parents.append(before.stack_oid)
    stack_oid = commit_tree_object(cwd, tree, message, parents)
    write_ref(cwd, stack_ref(after.branch), stack_oid)
    sync_patch_refs(cwd, after.branch, before.patches, after.patches)
    after.stack_oid = stack_oid
    after.meta_oid = meta_oid
    after.initialized = True
    return after


def empty_patch(cwd: str, oid: str) -> bool:
    try:
        return commit_tree(cwd, oid) == commit_tree(cwd, commit_parent(cwd, oid))
    except UserError:
        return False


def ensure_initialized(cwd: str, state: StackState) -> StackState:
    if state.initialized:
        return state
    new_state = StackState(
        branch=state.branch,
        initialized=True,
        head=state.head,
        prev=None,
        applied=[],
        unapplied=[],
        hidden=[],
        patches={},
        stack_oid=None,
        meta_oid=None,
    )
    tree = build_stack_tree(cwd, new_state)
    meta_oid = commit_tree_object(cwd, tree, "initialize", [])
    stack_oid = commit_tree_object(cwd, tree, "initialize", [meta_oid, state.head])
    write_ref(cwd, stack_ref(state.branch), stack_oid)
    new_state.stack_oid = stack_oid
    new_state.meta_oid = meta_oid
    return new_state


def validate_patch_name(name: str) -> None:
    if "/" in name:
        parse_error(
            f"invalid value '{name}' for '[patchname]': invalid patch name `{name}`: patch name may not contain '/'",
            "new:short",
        )
    if not PATCH_NAME_RE.match(name):
        parse_error(
            f"invalid value '{name}' for '[patchname]': invalid patch name `{name}`",
            "new:short",
        )


def slugify_patch_name(message: str, state: StackState) -> str:
    first_line = message.splitlines()[0] if message.splitlines() else "patch"
    base = re.sub(r"[^a-z0-9._-]+", "-", first_line.lower()).strip("-")
    base = re.sub(r"-{2,}", "-", base) or "patch"
    candidate = base
    suffix = 1
    while candidate in state.patches:
        suffix += 1
        candidate = f"{base}-{suffix}"
    return candidate


def parse_file_or_stdin(path: str) -> str:
    if path == "-":
        return sys.stdin.read()
    return Path(path).read_text(encoding="utf-8")


def build_tree_from_worktree(cwd: str, base_commit: str, paths: list[str], use_index: bool) -> str:
    root = repo_root(cwd)
    repo_paths = normalize_paths(cwd, paths)
    if use_index and not repo_paths:
        return git_ok(["write-tree"], cwd).strip()
    with tempfile.NamedTemporaryFile() as index_file:
        env = {"GIT_INDEX_FILE": index_file.name}
        git_ok(["read-tree", base_commit], root, env=env)
        if use_index:
            cached_paths = repo_paths or git_ok(["diff", "--cached", "--name-only"], cwd).splitlines()
            if cached_paths:
                diff_text = git_ok(["diff", "--cached", "--binary", "--", *cached_paths], cwd)
                if diff_text:
                    result = git(["apply", "--cached", "--allow-empty"], root, env=env, input_text=diff_text)
                    if result.returncode != 0:
                        raise UserError(result.stderr.strip() or "could not apply index changes")
        else:
            add_args = ["add", "-A"]
            if repo_paths:
                add_args.extend(["--", *repo_paths])
            else:
                add_args.append(".")
            result = git(add_args, root, env=env)
            if result.returncode != 0:
                raise UserError(result.stderr.strip() or "could not stage worktree changes")
        return git_ok(["write-tree"], root, env=env).strip()


def resolve_state_for_branch(cwd: str, branch: Optional[str]) -> StackState:
    ensure_repo(cwd)
    actual_branch = branch or current_branch(cwd)
    return load_stack(cwd, actual_branch)


def split_branch_revision(revision: str) -> tuple[Optional[str], str]:
    if revision.startswith("{base}") or ":" not in revision:
        return None, revision
    branch, remainder = revision.split(":", 1)
    if not branch or not remainder:
        return None, revision
    return branch, remainder


def resolve_revision(cwd: str, state: StackState, revision: Optional[str]) -> str:
    if revision is None:
        return state.head
    branch_override, inner = split_branch_revision(revision)
    target_state = load_stack(cwd, branch_override) if branch_override else state
    want_parent = False
    if inner.endswith("^") and inner != "^":
        want_parent = True
        inner = inner[:-1]
    if inner == "{base}":
        oid = stack_base_oid(cwd, target_state)
        return commit_parent(cwd, oid) if want_parent else oid
    if inner in target_state.patches:
        oid = target_state.patches[inner]
        return commit_parent(cwd, oid) if want_parent else oid
    resolved = git(["rev-parse", revision], cwd)
    if resolved.returncode != 0:
        stderr = resolved.stderr.strip()
        raise UserError(stderr or f"invalid revision `{revision}`")
    oid = resolved.stdout.strip()
    if want_parent:
        return commit_parent(cwd, oid)
    return oid


def resolve_patch_name(cwd: str, state: StackState, revision: Optional[str], showbranch: bool) -> str:
    if revision is None:
        name = state.applied[-1] if state.applied else "{base}"
        return f"{state.branch}:{name}" if showbranch else name
    branch_override, inner = split_branch_revision(revision)
    target_state = load_stack(cwd, branch_override) if branch_override else state
    target_branch = branch_override or state.branch
    if inner == "{base}":
        if branch_override and not stack_series(target_state):
            oid = resolve_revision(cwd, target_state, revision)
            user_error(f"patch name not found for revision `{oid}`")
        return f"{target_branch}:{{base}}" if showbranch else "{base}"
    if inner in target_state.patches:
        return f"{target_branch}:{inner}" if showbranch else inner
    oid = resolve_revision(cwd, target_state, revision)
    base_oid = stack_base_oid(cwd, target_state)
    for name, patch_commit in target_state.patches.items():
        if patch_commit == oid:
            return f"{target_branch}:{name}" if showbranch else name
    if oid == base_oid:
        return f"{target_branch}:{{base}}" if showbranch else "{base}"
    user_error(f"patch name not found for revision `{oid}`")
    return ""


def default_show_target(cwd: str, state: StackState) -> str:
    return state.applied[-1] if state.applied else state.head


def range_label(names: list[str]) -> str:
    return names[0] if len(names) == 1 else f"{names[0]}..{names[-1]}"


def select_push_patches(state: StackState, number: Optional[int], all_patches: bool, patch_names: list[str]) -> list[str]:
    if all_patches:
        selected = list(state.unapplied)
    elif number is not None:
        if number < 0:
            keep = min(len(state.unapplied), abs(number))
            selected = state.unapplied[: max(0, len(state.unapplied) - keep)]
        else:
            selected = state.unapplied[:number]
    elif patch_names:
        selected = []
        remaining = list(state.unapplied)
        for name in patch_names:
            if name not in remaining:
                patch_oid(state, name)
                user_error(f"patch `{name}` is not unapplied")
            selected.append(name)
            remaining.remove(name)
    else:
        selected = state.unapplied[:1]
    if not selected:
        user_error("no unapplied patches")
    return selected


def select_pop_patches(state: StackState, number: Optional[int], all_patches: bool, patch_names: list[str]) -> list[str]:
    if all_patches:
        selected = list(state.applied)
    elif number is not None:
        if number < 0:
            keep = min(len(state.applied), abs(number))
            selected = state.applied[keep:]
        else:
            selected = state.applied[max(0, len(state.applied) - number) :]
    elif patch_names:
        if not all(name in state.applied for name in patch_names):
            for name in patch_names:
                if name not in state.applied:
                    patch_oid(state, name)
                    user_error(f"patch `{name}` is not applied")
        first_index = min(state.applied.index(name) for name in patch_names)
        selected = state.applied[first_index:]
    else:
        selected = state.applied[-1:] if state.applied else []
    if not state.applied:
        user_error("no patches applied")
    if not selected:
        user_error("no patches applied")
    return selected


def pop_state(cwd: str, before: StackState, selected: list[str], message: str) -> StackState:
    state = StackState(
        branch=before.branch,
        initialized=before.initialized,
        head=before.head,
        prev=before.stack_oid,
        applied=list(before.applied),
        unapplied=list(before.unapplied),
        hidden=list(before.hidden),
        patches=dict(before.patches),
        stack_oid=before.stack_oid,
        meta_oid=before.meta_oid,
    )
    first_index = state.applied.index(selected[0])
    popped = state.applied[first_index:]
    state.applied = state.applied[:first_index]
    state.unapplied = popped + state.unapplied
    state.head = state.patches[state.applied[-1]] if state.applied else stack_base_oid(cwd, before)
    write_stack_state(cwd, before, state, message, head_changed=True)
    update_branch_head(cwd, state.branch, state.head, update_worktree=True)
    return state


def push_state(cwd: str, before: StackState, selected: list[str], message: str) -> StackState:
    state = StackState(
        branch=before.branch,
        initialized=before.initialized,
        head=before.head,
        prev=before.stack_oid,
        applied=list(before.applied),
        unapplied=list(before.unapplied),
        hidden=list(before.hidden),
        patches=dict(before.patches),
        stack_oid=before.stack_oid,
        meta_oid=before.meta_oid,
    )
    for name in selected:
        state.unapplied.remove(name)
        state.applied.append(name)
    state.head = state.patches[state.applied[-1]]
    write_stack_state(cwd, before, state, message, head_changed=True)
    update_branch_head(cwd, state.branch, state.head, update_worktree=True)
    return state


def delete_state(cwd: str, before: StackState, selected: list[str], message: str, head_changed: bool) -> StackState:
    state = StackState(
        branch=before.branch,
        initialized=before.initialized,
        head=before.head,
        prev=before.stack_oid,
        applied=[name for name in before.applied if name not in selected],
        unapplied=[name for name in before.unapplied if name not in selected],
        hidden=[name for name in before.hidden if name not in selected],
        patches={name: oid for name, oid in before.patches.items() if name not in selected},
        stack_oid=before.stack_oid,
        meta_oid=before.meta_oid,
    )
    if state.applied:
        state.head = state.patches[state.applied[-1]]
    elif head_changed:
        state.head = stack_base_oid(cwd, before)
    write_stack_state(cwd, before, state, message, head_changed=head_changed)
    if head_changed:
        update_branch_head(cwd, state.branch, state.head, update_worktree=True)
    return state


