def command_new(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["new"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("new"))
        return 0
    state = resolve_state_for_branch(cwd, None)
    branch = state.branch
    patch_name: Optional[str] = None
    message: Optional[str] = None
    refresh = False
    use_index = False
    force = False
    paths: list[str] = []
    index = 0
    positional: list[str] = []
    while index < len(args):
        token = args[index]
        if token == "--":
            paths.extend(args[index + 1 :])
            break
        if token in ("-n", "--name"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--name <name>' but none was supplied", "new:short")
            patch_name = args[index + 1]
            index += 2
            continue
        if token in ("-m", "--message"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--message <message>' but none was supplied", "new:short")
            message = args[index + 1]
            index += 2
            continue
        if token in ("-f", "--file"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--file <path>' but none was supplied", "new:short")
            message = parse_file_or_stdin(args[index + 1]).rstrip("\n")
            index += 2
            continue
        if token in ("-r", "--refresh"):
            refresh = True
            index += 1
            continue
        if token in ("-i", "--index"):
            use_index = True
            index += 1
            continue
        if token in ("-F", "--force"):
            force = True
            index += 1
            continue
        if token == "--color":
            if index + 1 >= len(args):
                parse_error("a value is required for '--color <when>' but none was supplied", "new:short")
            validate_color(args[index + 1], "new:short")
            index += 2
            continue
        if token.startswith("-"):
            parse_error(f"unexpected argument '{token}' found", "new:short")
        positional.append(token)
        index += 1
    if positional:
        if patch_name is not None:
            paths.extend(positional)
        else:
            patch_name = positional[0]
            paths.extend(positional[1:])
    if paths:
        refresh = True
    state = ensure_initialized(cwd, state)
    state = load_stack(cwd, branch)
    if message is None:
        message = patch_name or "patch"
    if patch_name is None:
        patch_name = slugify_patch_name(message, state)
    validate_patch_name(patch_name)
    if patch_exists(state, patch_name):
        user_error(f"patch `{patch_name}` already exists")
    parent = state.head
    if refresh or force:
        tree = build_tree_from_worktree(cwd, parent, paths, use_index)
    else:
        tree = commit_tree(cwd, parent)
    author = (*author_identity(cwd), current_time_text())
    committer = (*author_identity(cwd), current_time_text())
    commit_oid = commit_tree_object(cwd, tree, message, [parent], author=author, committer=committer)
    after = StackState(
        branch=branch,
        initialized=True,
        head=commit_oid,
        prev=state.stack_oid,
        applied=[*state.applied, patch_name],
        unapplied=list(state.unapplied),
        hidden=list(state.hidden),
        patches={**state.patches, patch_name: commit_oid},
        stack_oid=state.stack_oid,
        meta_oid=state.meta_oid,
    )
    write_stack_state(cwd, state, after, f"new: {patch_name}", head_changed=True)
    write_ref(cwd, patch_ref(branch, patch_name), commit_oid)
    if refresh:
        update_branch_head(cwd, branch, commit_oid, update_worktree=True)
    else:
        write_ref(cwd, branch_ref(branch), commit_oid)
    print(f"> {patch_name} (new)")
    return 0


