def command_series(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["series"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("series"))
        return 0
    state = resolve_state_for_branch(cwd, None)
    show_hidden = False
    select_applied = False
    select_unapplied = False
    select_hidden = False
    reverse = False
    count = False
    no_prefix = False
    show_empty = False
    index = 0
    patch_args: list[str] = []
    while index < len(args):
        token = args[index]
        if token in ("-a", "--all"):
            show_hidden = True
            index += 1
            continue
        if token in ("-A", "--applied"):
            select_applied = True
            index += 1
            continue
        if token in ("-U", "--unapplied"):
            select_unapplied = True
            index += 1
            continue
        if token in ("-H", "--hidden"):
            select_hidden = True
            index += 1
            continue
        if token in ("-r", "--reverse"):
            reverse = True
            index += 1
            continue
        if token in ("-c", "--count"):
            count = True
            index += 1
            continue
        if token in ("-P", "--no-prefix"):
            no_prefix = True
            index += 1
            continue
        if token in ("-e", "--empty"):
            show_empty = True
            index += 1
            continue
        if token == "--color":
            if index + 1 >= len(args):
                parse_error("a value is required for '--color <when>' but none was supplied", "series:short")
            validate_color(args[index + 1], "series:short")
            index += 2
            continue
        if token.startswith("-"):
            parse_error(f"unexpected argument '{token}' found", "series:short")
        patch_args.append(token)
        index += 1
    selected: list[str]
    if patch_args:
        selected = [name for name in stack_series(state) if name in patch_args]
    elif select_applied or select_unapplied or select_hidden:
        selected = []
        if select_applied:
            selected.extend(state.applied)
        if select_unapplied:
            selected.extend(state.unapplied)
        if select_hidden:
            selected.extend(state.hidden)
    else:
        selected = [*state.applied, *state.unapplied]
        if show_hidden:
            selected.extend(state.hidden)
    if reverse:
        selected = list(reversed(selected))
    if count:
        print(len(selected))
        return 0
    for name in selected:
        if name in state.applied:
            marker = ">" if state.applied and name == state.applied[-1] else "+"
        elif name in state.unapplied:
            marker = "-"
        else:
            marker = "!"
        line = name if no_prefix else f"{marker} {name}"
        if show_empty:
            line = ("*" if empty_patch(cwd, state.patches[name]) else " ") + line
        print(line)
    return 0


