    state = resolve_state_for_branch(cwd, None)
    only_applied = "-A" in args or "--applied" in args
    only_unapplied = "-U" in args or "--unapplied" in args
    selected: list[str] = []
    if only_applied:
        selected = [name for name in state.applied if empty_patch(cwd, state.patches[name])]
    elif only_unapplied:
        selected = [name for name in state.unapplied if empty_patch(cwd, state.patches[name])]
    else:
        selected = [name for name in stack_series(state) if empty_patch(cwd, state.patches[name])]
    if not selected:
        return 0
    applied_selected = [name for name in selected if name in state.applied]
    current = state
    if applied_selected:
        start = min(current.applied.index(name) for name in applied_selected)
        popped = current.applied[start:]
        current = pop_state(cwd, current, popped, "clean")
        print(f"- {range_label(popped)}")
        selected = popped + [name for name in selected if name not in popped]
    delete_state(cwd, current, selected, "clean", head_changed=bool(applied_selected))
    print(f"# {range_label(selected)}")
    return 0


def command_refresh(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["refresh"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("refresh"))
        return 0
    state = resolve_state_for_branch(cwd, None)
    if not state.applied:
        user_error("no patches applied")
    patch_name: Optional[str] = None
    message: Optional[str] = None
    use_index = False
    force = False
    paths: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if token in ("-p", "--patch"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--patch <patch>' but none was supplied", "refresh:short")
            patch_name = args[index + 1]
            index += 2
            continue
        if token in ("-m", "--message"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--message <message>' but none was supplied", "refresh:short")
            message = args[index + 1]
            index += 2
            continue
        if token in ("-f", "--file"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--file <path>' but none was supplied", "refresh:short")
            message = parse_file_or_stdin(args[index + 1]).rstrip("\n")
            index += 2
            continue
        if token in ("-i", "--index"):
            use_index = True
            index += 1
            continue
        if token in ("-F", "--force", "-u", "--update", "-a", "--annotate", "--submodules", "--no-submodules", "--no-verify", "-e", "--edit", "-d", "--diff", "-s", "--signoff", "--ack", "--review", "--author", "--authname", "--authemail", "--authdate", "--committer-date-is-author-date"):
            if token in ("-a", "--annotate", "-s", "--signoff", "--ack", "--review", "--author", "--authname", "--authemail", "--authdate") and index + 1 < len(args) and not args[index + 1].startswith("-"):
                index += 1
            force = force or token in ("-F", "--force")
            index += 1
            continue
        if token.startswith("--conflicts"):
            if "=" not in token and index + 1 < len(args) and not args[index + 1].startswith("-"):
                index += 1
            index += 1
            continue
        if token == "--":
            paths.extend(args[index + 1 :])
            break
        if token == "--color":
            if index + 1 >= len(args):
                parse_error("a value is required for '--color <when>' but none was supplied", "refresh:short")
            validate_color(args[index + 1], "refresh:short")
            index += 2
            continue
        if token.startswith("-"):
            parse_error(f"unexpected argument '{token}' found", "refresh:short")
        paths.append(token)
        index += 1
    patch_name = patch_name or state.applied[-1]
    if patch_name != state.applied[-1]:
        user_error("only the topmost patch may be refreshed")
    old_commit = patch_oid(state, patch_name)
    base_commit = commit_parent(cwd, old_commit)
    if message is None:
        message = commit_message(cwd, old_commit)
    author = commit_author_info(cwd, old_commit)
    committer = (*author_identity(cwd), current_time_text())
    tree = build_tree_from_worktree(cwd, base_commit, paths, use_index)
    new_commit = commit_tree_object(cwd, tree, message, [base_commit], author=author, committer=committer)
    after = StackState(
        branch=state.branch,
        initialized=True,
        head=new_commit,
        prev=state.stack_oid,
        applied=list(state.applied),
        unapplied=list(state.unapplied),
        hidden=list(state.hidden),
        patches={**state.patches, patch_name: new_commit},
        stack_oid=state.stack_oid,
        meta_oid=state.meta_oid,
    )
    write_stack_state(
        cwd,
        state,
        after,
        f"refresh {patch_name}",
        head_changed=True,
        extra_meta_messages=["refresh refresh-temp (create temporary patch)"],
    )
    update_branch_head(cwd, after.branch, new_commit, update_worktree=True)
    print("> refresh-temp (new)")
    print("- refresh-temp")
    print("# refresh-temp")
    print(f"& {patch_name}")
    print(f"> {patch_name}")
    return 0


def command_rename(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["rename"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("rename"))
        return 0
    state = resolve_state_for_branch(cwd, None)
    tokens = [token for token in args if token not in ("--color",)]
    if len(tokens) == 1:
        if not state.applied:
            user_error("no patches applied")
        old_name = state.applied[-1]
        new_name = tokens[0]
    elif len(tokens) == 2:
        old_name, new_name = tokens
    else:
        parse_error("the following required arguments were not provided:\n  <patches>...", "rename:short")
    validate_patch_name(new_name)
    old_oid = patch_oid(state, old_name)
    if new_name in state.patches:
        user_error(f"patch `{new_name}` already exists")
    def rename_in(names: Iterable[str]) -> list[str]:
        return [new_name if name == old_name else name for name in names]
    after = StackState(
        branch=state.branch,
        initialized=True,
        head=state.head,
        prev=state.stack_oid,
        applied=rename_in(state.applied),
        unapplied=rename_in(state.unapplied),
        hidden=rename_in(state.hidden),
        patches={new_name if name == old_name else name: oid for name, oid in state.patches.items() if name != old_name or True},
        stack_oid=state.stack_oid,
        meta_oid=state.meta_oid,
    )
    after.patches.pop(old_name, None)
    after.patches[new_name] = old_oid
    write_stack_state(cwd, state, after, f"rename {old_name} {new_name}", head_changed=False)
    delete_ref(cwd, patch_ref(state.branch, old_name))
    write_ref(cwd, patch_ref(state.branch, new_name), old_oid)
    print(f"{old_name} => {new_name}")
    if after.applied:
        print(f"> {after.applied[-1]}")
    return 0


