def command_branch(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["branch"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("branch"))
        return 0
    ensure_repo(cwd)
    if not args:
        print(current_branch(cwd))
        return 0
    if args[0] in ("--list", "-l"):
        current = current_branch(cwd)
        names = git_ok(["for-each-ref", "--format=%(refname:short)", "refs/heads"], cwd).splitlines()
        width = max((len(name) for name in names), default=0) + 2
        for name in names:
            marker = ">" if name == current else " "
            stg_marker = "s" if ref_exists(cwd, stack_ref(name)) else " "
            print(f"{marker} {stg_marker} \t{name.ljust(width)}|")
        return 0
    if args[0] in ("--create", "-c"):
        if len(args) < 2:
            parse_error("the following required arguments were not provided:\n  <new-branch>", "branch:short")
        new_branch = args[1]
        committish = args[2] if len(args) > 2 else None
        checkout_args = ["checkout", "-q", "-b", new_branch]
        if committish:
            checkout_args.append(committish)
        result = git(checkout_args, cwd)
        if result.returncode != 0:
            raise UserError(result.stderr.strip() or f"could not create branch `{new_branch}`")
        print("info: Recording as a local branch")
        new_state = load_stack(cwd, new_branch)
        if not new_state.initialized:
            ensure_initialized(cwd, new_state)
        return 0
    if args[0] == "--cleanup":
        force = "--force" in args
        target = next((token for token in args[1:] if not token.startswith("-")), current_branch(cwd))
        state = load_stack(cwd, target)
        if stack_series(state) and not force:
            user_error("clean up not permitted: the series still contains patches (override with --force)")
        delete_ref(cwd, stack_ref(target))
        for name in list(state.patches):
            delete_ref(cwd, patch_ref(target, name))
        return 0
    if args[0] in ("--rename", "-r"):
        filtered = [token for token in args[1:] if not token.startswith("-")]
        if len(filtered) == 1:
            old_name = current_branch(cwd)
            new_name = filtered[0]
        elif len(filtered) == 2:
            old_name, new_name = filtered
        else:
            parse_error("the following required arguments were not provided:\n  <new-name>", "branch:short")
        result = git(["branch", "-m", old_name, new_name], cwd)
        if result.returncode != 0:
            raise UserError(result.stderr.strip() or "could not rename branch")
        if ref_exists(cwd, stack_ref(old_name)):
            old_stack = git_ok(["rev-parse", stack_ref(old_name)], cwd).strip()
            write_ref(cwd, stack_ref(new_name), old_stack)
            delete_ref(cwd, stack_ref(old_name))
            patch_refs = git_ok(["for-each-ref", "--format=%(refname:strip=3)", f"refs/patches/{old_name}"], cwd).splitlines()
            for patch_name in patch_refs:
                oid = git_ok(["rev-parse", patch_ref(old_name, patch_name)], cwd).strip()
                write_ref(cwd, patch_ref(new_name, patch_name), oid)
                delete_ref(cwd, patch_ref(old_name, patch_name))
        return 0
    if args[0] in ("--delete", "-D"):
        force = "--force" in args
        target = next((token for token in args[1:] if not token.startswith("-")), None)
        if not target:
            parse_error("the following required arguments were not provided:\n  [branch]", "branch:short")
        result = git(["branch", "-D" if force else "-d", target], cwd)
        if result.returncode != 0:
            raise UserError(result.stderr.strip() or f"could not delete branch `{target}`")
        delete_ref(cwd, stack_ref(target))
        patch_names = git_ok(["for-each-ref", "--format=%(refname:strip=3)", f"refs/patches/{target}"], cwd).splitlines()
        for patch_name in patch_names:
            delete_ref(cwd, patch_ref(target, patch_name))
        return 0
    if args[0].startswith("-"):
        user_error(f"command `{args[0]}` is not implemented")
    result = git(["checkout", "-q", args[0]], cwd)
    if result.returncode != 0:
        raise UserError(result.stderr.strip() or f"could not switch to branch `{args[0]}`")
    return 0


