        base = StackState(
            branch=state.branch,
            initialized=True,
            head=state.head,
            prev=None,
            applied=list(state.applied),
            unapplied=list(state.unapplied),
            hidden=list(state.hidden),
            patches=dict(state.patches),
            stack_oid=None,
            meta_oid=None,
        )
        after = write_stack_state(cwd, base, base, "initialize", head_changed=True)
        write_ref(cwd, stack_ref(state.branch), after.stack_oid or "")
        return 0
    if graphical:
        return 0
    git_args = ["log"]
    if limit:
        git_args.extend(["-n", limit])
    if full:
        git_args.append("--format=fuller")
    elif show_diff:
        git_args.append("-p")
    else:
        git_args.append("--format=%h   %aD   %s")
    git_args.append(state.meta_oid)
    output = git_ok(git_args, cwd)
    if patch_filters and not (full or show_diff):
        lines = [line for line in output.splitlines() if any(patch in line for patch in patch_filters)]
        if lines:
            print("\n".join(lines))
    else:
        sys.stdout.write(output)
    return 0


def command_commit(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["commit"]))
        return 0
    if args == ["-h"]:
        print_text(short_help_for("commit"))
        return 0
    state = resolve_state_for_branch(cwd, None)
    if not state.applied:
        user_error("no patches applied")
    number: Optional[int] = None
    all_patches = False
    selected: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if token in ("-n", "--number"):
            if index + 1 >= len(args):
                parse_error("a value is required for '--number <number>' but none was supplied", "commit:short")
            number = int(args[index + 1])
            index += 2
            continue
        if token in ("-a", "--all"):
            all_patches = True
            index += 1
            continue
        if token == "--allow-empty":
            index += 1
            continue
        if token == "--color":
            if index + 1 >= len(args):
                parse_error("a value is required for '--color <when>' but none was supplied", "commit:short")
            validate_color(args[index + 1], "commit:short")
            index += 2
            continue
        if token.startswith("-"):
            parse_error(f"unexpected argument '{token}' found", "commit:short")
        selected.append(token)
        index += 1
    if all_patches:
        selected = list(state.applied)
    elif number is not None:
        selected = state.applied[:number]
    elif not selected:
        selected = state.applied[:1]
    if not selected:
        user_error("no patches applied")
    if selected != state.applied[: len(selected)]:
        user_error("only bottommost applied patches may be committed")
    after = StackState(
        branch=state.branch,
        initialized=True,
        head=state.head,
        prev=state.stack_oid,
        applied=state.applied[len(selected) :],
        unapplied=list(state.unapplied),
        hidden=list(state.hidden),
        patches={name: oid for name, oid in state.patches.items() if name not in selected},
        stack_oid=state.stack_oid,
        meta_oid=state.meta_oid,
    )
    write_stack_state(cwd, state, after, "commit", head_changed=False)
    sync_patch_refs(cwd, state.branch, state.patches, after.patches)
    print(f"# {range_label(selected)}")
    if after.applied:
        print(f"> {after.applied[-1]}")
    return 0


def command_version(cwd: str, args: list[str]) -> int:
    if any(token == "--help" for token in args):
        print_text(long_help_for(["version"]))
        return 0
    short = False
    index = 0
    while index < len(args):
        token = args[index]
        if token in ("-h",):
            print_text(short_help_for("version"))
            return 0
        if token in ("-s", "--short"):
            short = True
            index += 1
            continue
        if token == "--color":
            if index + 1 >= len(args):
                parse_error("a value is required for '--color <when>' but none was supplied", "version:short")
            validate_color(args[index + 1], "version:short")
            index += 2
            continue
        parse_error(f"unexpected argument '{token}' found", "version:short")
    key = "version_short" if short else "version"
    print_text(HELP_TEXTS[key]["stdout"])
    return 0


def completion_list_output(which: str, style: str) -> str:
    if which == "aliases":
        items = list(ALIASES)
    elif which == "commands":
        items = COMMANDS
    else:
        items = [*COMMANDS, *ALIASES]
    if style == "fish":
        return "\n".join(f"{item}\t{COMMAND_DESCRIPTIONS.get(item, '')}" for item in items) + "\n"
    if style in ("zsh", "asciidoc"):
        return "\n".join(items) + "\n"
    return "\n".join(items) + "\n"


def completion_script(shell_name: str) -> str:
    if shell_name == "bash":
        commands = " ".join([*COMMANDS, *ALIASES])
        return (
            "# -*- shell-script -*-\n"
            "#\n"
            "# SPDX-License-Identifier: GPL-2.0-only\n"
            "#\n"
            "# bash completion script for StGit (generated by clean-room implementation)\n"
            "_stg_completions()\n"
            "{\n"
            f"    COMPREPLY=( $(compgen -W '{commands}' -- \"${{COMP_WORDS[COMP_CWORD]}}\") )\n"
            "}\n"
            "complete -F _stg_completions stg\n"
        )
    if shell_name == "fish":
        return "\n".join(f"complete -c stg -f -a '{name}'" for name in [*COMMANDS, *ALIASES]) + "\n"
    if shell_name == "zsh":
        return "#compdef stg\n_arguments '*:command:->command'\n"
    return ""


def write_or_stdout(output: str, path: Optional[str]) -> None:
    if path:
        Path(path).write_text(output, encoding="ascii")
    else:
        sys.stdout.write(output)


def command_completion(cwd: str, args: list[str]) -> int:
    if not args:
        parse_error(
            "'stg completion' requires a subcommand but one was not provided",
            "completion:short",
            extra="  [subcommands: bash, fish, zsh, list, man, help]",
        )
    if args[0] in ("-h",):
        print_text(short_help_for("completion"))
        return 0
    if "--help" in args:
        if args[0] == "list":
            print_text(long_help_for(["completion", "list"]))
            return 0
        print_text(long_help_for(["completion"]))
        return 0
    output_path = None
    color_values: list[str] = []
    style = "name-only"
    shell_or_mode = args[0]
    rest = args[1:]
    index = 0
    while index < len(rest):
        token = rest[index]
        if token in ("-o", "--output"):
            if index + 1 >= len(rest):
                parse_error("a value is required for '--output <path>' but none was supplied", "completion:short")
            output_path = rest[index + 1]
            index += 2
            continue
        if token == "--style":
            if index + 1 >= len(rest):
                parse_error("a value is required for '--style <style>' but none was supplied", "completion_list:short")
            style = rest[index + 1]
            index += 2
            continue
        if token == "--color":
            if index + 1 >= len(rest):
                parse_error("a value is required for '--color <when>' but none was supplied", "completion:short")
            color_values.append(rest[index + 1])
            index += 2
            continue
        if token.startswith("-"):
            parse_error(f"unexpected argument '{token}' found", "completion:short")
        break
    for value in color_values:
        validate_color(value, "completion:short")
    if shell_or_mode == "help":
        print_text(long_help_for(["completion"]))
        return 0
    if shell_or_mode in ("bash", "fish", "zsh"):
        output = completion_script(shell_or_mode)
        write_or_stdout(output, output_path)
        return 0
    if shell_or_mode == "man":
        write_or_stdout("", output_path)
        return 0
    if shell_or_mode == "list":
        if not rest or all(token.startswith("-") for token in rest):
            parse_error(
                "'stg completion list' requires a subcommand but one was not provided",
                "completion_list:short",
                extra="  [subcommands: aliases, commands, commands-and-aliases, help]",
            )
        subcommand = next((token for token in rest if not token.startswith("-")), None)
        if subcommand == "help":
            print_text(long_help_for(["completion", "list"]))
            return 0
        if subcommand not in ("aliases", "commands", "commands-and-aliases"):
            parse_error(f"unrecognized subcommand '{subcommand}'", "completion_list:short")
        output = completion_list_output(subcommand, style)
        write_or_stdout(output, output_path)
        return 0
    parse_error(f"unrecognized subcommand '{shell_or_mode}'", "completion:short")
    return 1


def alias_command(cwd: str, command: str, args: list[str]) -> int:
    if "--help" in args:
        print_text(long_help_for([command]))
        return 0
    return passthrough(["git", *ALIASES[command], *args], cwd)


def command_help(cwd: str, args: list[str]) -> int:
    if not args:
        print_text(HELP_TEXTS["top_long"]["stdout"])
        return 0
    if args == ["help"]:
        print_text(HELP_TEXTS["help_help"]["stdout"])
        return 0
    print_text(long_help_for(args))
    return 0


def not_implemented(command: str) -> int:
    user_error(f"command `{command}` is not implemented")
    return 2


def dispatch_command(cwd: str, command: str, args: list[str]) -> int:
    if command in ALIASES:
        return alias_command(cwd, command, args)
    if command == "help":
        return command_help(cwd, args)
    if command == "version":
        return command_version(cwd, args)
    if command == "completion":
        return command_completion(cwd, args)
    if command == "init":
        return command_init(cwd, args)
    if command == "new":
        return command_new(cwd, args)
    if command == "refresh":
        return command_refresh(cwd, args)
    if command == "series":
        return command_series(cwd, args)
    if command == "top":
        return command_top(cwd, args)
    if command == "next":
        return command_next(cwd, args)
    if command == "prev":
        return command_prev(cwd, args)
    if command == "push":
        return command_push(cwd, args)
    if command == "pop":
        return command_pop(cwd, args)
    if command == "goto":
        return command_goto(cwd, args)
    if command == "delete":
        return command_delete(cwd, args)
    if command == "clean":
        return command_clean(cwd, args)
    if command == "rename":
        return command_rename(cwd, args)
    if command == "hide":
        return command_hide(cwd, args)
    if command == "unhide":
        return command_unhide(cwd, args)
    if command == "branch":
        return command_branch(cwd, args)
    if command == "id":
        return command_id(cwd, args)
    if command == "name":
        return command_name(cwd, args)
    if command == "files":
        return command_files(cwd, args)
    if command == "show":
        return command_show(cwd, args)
    if command == "diff":
        return command_diff(cwd, args)
    if command == "patches":
        return command_patches(cwd, args)
    if command == "log":
        return command_log(cwd, args)
    if command == "commit":
        return command_commit(cwd, args)
    if command in COMMANDS:
        return not_implemented(command)
    parse_error(f"unrecognized subcommand '{command}'", "top_short")
    return 1


def parse_global(argv: list[str]) -> tuple[str, list[str]]:
    cwd = os.getcwd()
    index = 0
    pending_colors: list[str] = []
    while index < len(argv):
        token = argv[index]
        if token == "-C":
            if index + 1 >= len(argv):
                parse_error("a value is required for '-C <path>' but none was supplied", "top_short")
            path = argv[index + 1]
            cwd = path if os.path.isabs(path) else os.path.normpath(os.path.join(cwd, path))
            index += 2
            continue
        if token == "--color":
            if index + 1 >= len(argv):
                parse_error("a value is required for '--color <when>' but none was supplied", "top_short")
            pending_colors.append(argv[index + 1])
            index += 2
            continue
        if token == "--version":
            print_text(HELP_TEXTS["version"]["stdout"])
            raise SystemExit(0)
        if token == "--help":
            print_text(HELP_TEXTS["top_long"]["stdout"])
            raise SystemExit(0)
        if token == "-h":
            print_text(HELP_TEXTS["top_short"]["stdout"])
            raise SystemExit(0)
        break
    if index >= len(argv):
        for value in pending_colors:
            validate_color(value, "top_short")
        return cwd, []
    if argv[index] != "help":
        for value in pending_colors:
            validate_color(value, "top_short")
    return cwd, argv[index:]


def main(argv: list[str]) -> int:
    if not argv:
        print_text(HELP_TEXTS["top_noargs"]["stdout"])
        return 1
    cwd, remainder = parse_global(argv)
    if not remainder:
        print_text(HELP_TEXTS["top_noargs"]["stdout"])
        return 1
    return dispatch_command(cwd, remainder[0], remainder[1:])


def run(argv: list[str]) -> int:
    try:
        return main(argv)
    except ParseError as exc:
        print(f"error: {exc.message}", file=sys.stderr)
        if exc.extra:
            print(exc.extra, file=sys.stderr)
        print(file=sys.stderr)
        print(usage_block(exc.usage_key), file=sys.stderr)
        print(file=sys.stderr)
        print("For more information, try '--help'.", file=sys.stderr)
        return 1
    except UserError as exc:
        print(f"error: {exc.message}", file=sys.stderr)
        return exc.code


if __name__ == "__main__":
    sys.exit(run(sys.argv[1:]))

